steps.script:
var m = tree.current_scene
var bad = []
for o in m.army_options:
	var id = str(o.id)
	if not ArmyListManager.is_army_selectable(id) or id.ends_with("_test") or id.contains("repro") or id.begins_with("tutorial_"):
		bad.append(id)
return ",".join(bad)

var m = tree.current_scene
var ids = []
for o in m.army_options:
	ids.append(str(o.id))
var missing = []
for a in ArmyListManager.army_allowlist:
	if a in ArmyListManager.bundled_armies and not a in ids:
		missing.append(a)
return ",".join(missing)

var stack = [tree.root]
while not stack.is_empty():
	var n = stack.pop_back()
	if n is Button and n.text == "Not now" and n.is_visible_in_tree():
		n.pressed.emit()
		return "dismissed"
	stack.append_array(n.get_children())
return "none"
